  $str$&lt;div id=&quot;program_preview&quot;&gt;&lt;span class=&quot;poster_img&quot;&gt;&lt;img title=&quot;&quot; alt=&quot;名筆を夢見る, 2018. 11. 5. - 2019. 1. 20., Special Exhibition Hall (3F)&quot; src=&quot;http://www.hangeul.go.kr/upload/namo/images/000137/exhibitionposter020_298_447.jpg&quot;&gt;&lt;/span&gt; 
