nt().addClass("on"); $(this).next().css("display", "block"); }); }); $(document).ready(function () { $(".photoContent").hide(); $(".photoContent:first").show(); $("#photo li h5").bind("click", function (e) { e.preventDefault(); $("#photo li").removeClass("onn"); $("#photo li .photoContent").css("display", "none"); $(this).parent().addClass("onn"); $(this).next().css("display", "block"); }); });$str$,
