ition .description p{margin:4px 0 0 0;font-size:0.75em;font-style:italic;} #subTabC{position:relative;display:block;height:500px;width:99.9%;} #subTabC .subTabCContent{display:block;text-align:center;vertical-align:top} #subTabC .subTabCContent img{display:block;} #subTabC ul{text-align:center} #subTabC ul li{float:left;list-style:none;background:none;text-align:left} #subTabC ul li h5{position:absolute;display:block;top:10px;margin:0;height:20px;width:18px;cursor:pointer;background:url(http://www.hangeul.go.kr/images/new/slide_dot.png) 0px 2px no-repeat;} #subTabC ul li.on h5{background:url(http://www.hangeul.go.kr/images/new/slide_dot.png) -16px 2px no-repeat;} #subTabC ul li h5.subTabCmu1{left:0;} #subTabC ul li h5.subTabCmu2{left:20px} #subTabC ul li h5.subTabCmu3{left:40px} #subTabC ul li h5.subTabCmu4{left:60px} #subTabC ul li h5.subTabCmu5{left:80px} #subTabC ul li h5.subTabCmu6{left:100px} #subTabC ul li h5.subTabCmu7{left:120px} #subTabC ul li h5.subTabCmu8{left:140px;} #subTabC ul li h5.subTabCmu9{left:160px} #subTabC ul li h5.subTabCmu10{left:180px} #subTabC ul li h5.subTabCmu11{left:200px} #subTabC ul li h5.subTabCmu12{left:220px} #subTabC ul li h5.subTabCmu13{left:240px} #subTabC ul li h5.subTabCmu14{left:260px} #subTabC ul li h5.subTabCmu15{left:280px} -->   $(document).ready(function () { $(".subTabCContent").hide(); $(".subTabCContent:first").show(); $("#subTabC li h5").bind("click", function (e) { e.preventDefault(); $("#subTabC li").removeClass("on"); $("#subTabC li .subTabCContent").css("display", "none"); $(this).parent().addClass("on"); $(this).next().css("display", "block"); }); });$str$,
