10{left:180px} #photo ul li .photomu11{left:200px} #photo ul li .photomu12{left:220px} #photo ul li .photomu13{left:240px} #photo ul li .photomu14{left:260px} #photo ul li .photomu15{left:280px} -->   $(document).ready(function () { $(".subTabCContent").hide(); $(".subTabCContent:first").show(); $("#subTabC li h5").bind("click", function (e) { e.preventDefault(); $("#subTabC li").removeClass("on"); $("#subTabC li .subTabCContent").css("display", "none"); $(this).parent().addClass("on"); $(this).next().css("display", "block"); }); }); $(document).ready(function () { $(".photoContent").hide(); $(".photoContent:first").show(); $("#photo li h5").bind("click", function (e) { e.preventDefault(); $("#photo li").removeClass("onn"); $("#photo li .photoContent").css("display", "none"); $(this).parent().addClass("onn"); $(this).next().css("display", "block"); }); });$str$,
