n;margin:40px 0 0px 1px;font-size:1.3em;border-top:0} .exhibition_composition ul{margin:10px 0 0 0;padding:0} .exhibition_composition ul li{padding:12px;border-bottom:1px dashed #ccc;list-style-type:none;list-style-position:inside} .exhibition_composition p{margin:20px auto;padding:0 9px;font-size:1.25em;line-height:1.7em} .exhibition_composition .linktype1{color:#00f} .exhibition_composition .linktype1:hover{text-decoration:underline} .exhibition_composition .text_small{color:#999;} #subTabC{position:relative;display:block;height:500px;width:99.9%;} #subTabC .subTabCContent{display:block;text-align:center;vertical-align:top} #subTabC .subTabCContent img{display:block;} #subTabC ul{text-align:center} #subTabC ul li{float:left;list-style:none;background:none;text-align:right} #subTabC ul li h5{position:absolute;display:block;top:10px;margin:0 10px 0 375px;height:20px;width:18px;cursor:pointer;background:url(http://www.hangeul.go.kr/images/new/slide_dot.png) 0px 2px no-repeat;} #subTabC ul li.on h5{background:url(http://www.hangeul.go.kr/images/new/slide_dot.png) -16px 2px no-repeat;} #subTabC ul li h5.subTabCmu1{left:0;} #subTabC ul li h5.subTabCmu2{left:20px} #subTabC ul li h5.subTabCmu3{left:40px} #subTabC ul li h5.subTabCmu4{left:60px} #subTabC ul li h5.subTabCmu5{left:80px} #subTabC ul li h5.subTabCmu6{left:100px} #subTabC ul li h5.subTabCmu7{left:120px} #subTabC ul li h5.subTabCmu8{left:140px;} #subTabC ul li h5.subTabCmu9{left:160px} #subTabC ul li h5.subTabCmu10{left:180px} #subTabC ul li h5.subTabCmu11{left:200px} #subTabC ul li h5.subTabCmu12{left:220px} #subTabC ul li h5.subTabCmu13{left:240px} #subTabC ul li h5.subTabCmu14{left:260px} #subTabC ul li h5.subTabCmu15{left:280px} -->   $(document).ready(function () { $(".subTabCContent").hide(); $(".subTabCContent:first").show(); $("#subTabC li h5").bind("click", function (e) { e.preventDefault(); $("#subTabC li").removeClass("on"); $("#subTabC li .subTabCContent").css("display", "none"); $(this).parent().addC